<script setup lang="ts">
definePageMeta({layout:'admin',middleware:'admin'})
const {data:stats,error:statsError,refresh}=await useFetch<any>('/api/admin/summary')
const {data:appointments}=await useFetch<any[]>('/api/admin/appointments',{query:{status:'confirmed'}})
const today=computed(()=>stats.value?.date||'')
const recent=computed(()=>appointments.value?.filter(a=>a.date>=today.value).sort((a,b)=>a.start_at.localeCompare(b.start_at)).slice(0,8)||[])
const summary=computed(()=>[{title:'نوبت‌های امروز',value:stats.value?.today||0,icon:'calendar-check',sub:'برنامه مراجعه امروز'},{title:'نوبت‌های آینده',value:stats.value?.upcoming||0,icon:'calendar-days',sub:'نوبت‌های تأییدشده'},{title:'کل نوبت‌ها',value:stats.value?.total||0,icon:'clipboard-list',sub:'از ابتدا تاکنون'},{title:'مراجعه انجام‌شده',value:stats.value?.completed||0,icon:'check-circle-2',sub:'نوبت‌های تکمیل‌شده'}])
useSeoMeta({title:'داشبورد مدیریت | دکتر آزاده مهرداد',robots:'noindex,nofollow'})
</script>
<template><div><div class="flex flex-wrap gap-4 justify-between items-center mb-9"><div><span class="eyebrow">نمای کلی مطب</span><h1 class="text-3xl font-extrabold mt-2 text-jade-800">داشبورد مدیریت</h1><p class="text-xs text-[#8aa094] mt-2">سلام، به پنل مدیریت مطب خوش آمدید.</p></div><NuxtLink to="/admin/appointments" class="btn-main"><Icon name="calendar-days" :size="17" /> مدیریت نوبت‌ها</NuxtLink></div><p v-if="statsError" class="bg-red-50 text-red-600 p-4 rounded-xl text-xs mb-5">دریافت آمار انجام نشد. اتصال پایگاه داده را بررسی کنید.</p><div class="grid sm:grid-cols-2 xl:grid-cols-4 gap-5"><div v-for="(s,i) in summary" :key="s.title" class="glass-card p-6"><div class="flex items-center justify-between mb-7"><span class="text-[12px] text-[#82998c] font-bold">{{s.title}}</span><span class="w-11 h-11 grid place-items-center rounded-xl" :class="i===0?'text-[#348c75] bg-[#e9f6ee]':i===1?'text-[#5072ab] bg-[#ecf3fc]':i===2?'text-[#aa8862] bg-[#fbf2e8]':'text-[#8c699f] bg-[#f7f0fb]'"><Icon :name="s.icon" :size="22" /></span></div><p class="text-[32px] font-black text-jade-800 leading-none">{{faNumber(s.value)}}</p><p class="text-[11px] text-[#acbbb0] mt-3">{{s.sub}}</p></div></div><div class="grid xl:grid-cols-[1.6fr_1fr] gap-6 mt-8"><div class="glass-card overflow-hidden"><div class="p-6 flex justify-between items-center"><div><h2 class="font-bold text-jade-800">نوبت‌های پیش رو</h2><p class="text-[11px] text-[#95aa9e] mt-1">جدیدترین برنامه مراجعه بیماران</p></div><NuxtLink to="/admin/appointments" class="text-xs font-bold text-jade-700">مشاهده همه</NuxtLink></div><div class="overflow-x-auto"><table class="admin-table"><thead><tr><th>بیمار</th><th>خدمت</th><th>تاریخ</th><th>ساعت</th><th>وضعیت</th></tr></thead><tbody><tr v-for="a in recent" :key="a.id"><td class="font-bold">{{a.patient_name}}</td><td>{{a.service}}</td><td>{{faDate(a.date)}}</td><td dir="ltr">{{a.time}}</td><td><span class="status-pill status-confirmed">تأییدشده</span></td></tr><tr v-if="!recent.length"><td colspan="5" class="!py-12 text-center">نوبت آینده‌ای ثبت نشده است.</td></tr></tbody></table></div></div><div class="glass-card p-7"><h2 class="font-bold text-jade-800 mb-5">دسترسی سریع</h2><div class="space-y-3"><NuxtLink v-for="link in [{to:'/admin/appointments',icon:'calendar-days',title:'مدیریت نوبت‌ها',desc:'مشاهده، لغو و تغییر زمان'},{to:'/admin/schedule',icon:'calendar-off',title:'تعطیلات و ساعات کاری',desc:'مدیریت تقویم مطب'},{to:'/admin/services',icon:'stethoscope',title:'ویرایش خدمات',desc:'زمان هر خدمت و فعال‌سازی'},{to:'/admin/settings',icon:'settings',title:'اطلاعات مطب',desc:'معرفی، آدرس و تماس'}]" :key="link.to" :to="link.to" class="flex items-center gap-3 p-4 bg-[#f6faf7] rounded-xl hover:bg-[#e9f5ee]"><Icon :name="link.icon" class="text-jade-700" :size="20" /><span class="flex-1"><strong class="block text-xs text-jade-800">{{link.title}}</strong><small class="text-[10px] text-[#95a99d] mt-1 block">{{link.desc}}</small></span><Icon name="chevron-left" :size="16" class="text-[#91aa9d]" /></NuxtLink></div></div></div></div></template>
